import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();
        double minError = 1e15;
        long resNum = 0, resDen = 1;

        for (long denom = 1; denom <= n; ++denom) {
            long num = (x * denom) / y;

            // Lambda equivalent as a method
            class UpdateResult {
                void update(long candidateNum) {
                    double error = Math.abs(x * denom - candidateNum * y) / (double)(y * denom);
                    if (error < minError) {
                        minError = error;
                        resNum = candidateNum;
                        resDen = denom;
                    }
                }
            }
            UpdateResult updater = new UpdateResult();

            if (num > 0 && (x * denom - (num - 1) * y) == 0) {
                System.out.println((num - 1) + "/" + denom);
                return;
            }
            if ((x * denom - num * y) == 0) {
                System.out.println(num + "/" + denom);
                return;
            }
            if ((x * denom - (num + 1) * y) == 0) {
                System.out.println((num + 1) + "/" + denom);
                return;
            }

            updater.update(num - 1);
            updater.update(num);
            updater.update(num + 1);
        }
        System.out.println(resNum + "/" + resDen);
    }
}
